insert into public.faq_categories (id, slug, title, description, sort_order, is_active) values ('a0000001-0001-4001-8001-000000000007', 'handover-move-in', 'Handover & Move-in', 'Key collection, snagging, inspections, and possession day.', 6, true) on conflict (slug) do update set title = excluded.title, description = excluded.description, sort_order = excluded.sort_order, updated_at = now();
