insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'how-much-deposit-do-i-pay-when-renting-in-dubai', 'How much deposit do I pay when renting in Dubai?', '<p>Most landlords require a security deposit of 5–10% of the annual rent, refundable at end of tenancy subject to property condition. Your <a href="/account/transactions">property applications</a> shows the exact deposit before you pay. See our <a href="/pages/renting-guide">Renting Guide</a> for a full cost breakdown.</p>', 'How much deposit do I pay when renting in Dubai?', 0, true from public.faq_categories where slug = 'renting-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'can-i-pay-rent-in-multiple-cheques-in-dubai', 'Can I pay rent in multiple cheques in Dubai?', '<p>Yes. Cheque plans vary by property — from one annual cheque to twelve monthly post-dated cheques. Each listing displays the available plan. Browse <a href="/collection/rentals">holiday and long-term rentals</a> and filter by payment terms, or <a href="/pages/contact">contact our team</a> for custom arrangements.</p>', 'Can I pay rent in multiple cheques in Dubai?', 1, true from public.faq_categories where slug = 'renting-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-is-ejari-and-do-i-need-it-for-my-rental', 'What is Ejari and do I need it for my rental?', '<p>Ejari is Dubai''s official tenancy registration with RERA. It protects both tenant and landlord and is required for DEWA connection and visa processes. We coordinate Ejari as part of move-in — details in <a href="/pages/shipping">Handover Information</a> and <a href="/pages/renting-guide">Renting Guide</a>.</p>', 'What is Ejari and do I need it for my rental?', 2, true from public.faq_categories where slug = 'renting-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'how-long-is-a-standard-dubai-tenancy-contract', 'How long is a standard Dubai tenancy contract?', '<p>Most residential leases run 12 months. Some short-term <a href="/collection/rentals">holiday and long-term rentals</a> may offer 3–6 month terms. Contract duration is confirmed in your <a href="/account/transactions">property applications</a> before signing.</p>', 'How long is a standard Dubai tenancy contract?', 3, true from public.faq_categories where slug = 'renting-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'can-tourists-rent-a-property-in-dubai', 'Can tourists rent a property in Dubai?', '<p>Yes, many vacation and furnished rentals accept tourist visas with valid passport copies. Long-term leases typically require Emirates ID or a valid UAE visa. Submit an inquiry on any listing or use <a href="/search">property search</a> to find furnished options.</p>', 'Can tourists rent a property in Dubai?', 4, true from public.faq_categories where slug = 'renting-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-documents-do-i-need-to-rent-an-apartment-in-dubai', 'What documents do I need to rent an apartment in Dubai?', '<p>Usually: passport, UAE visa/Emirates ID, salary certificate or bank statements, and sometimes a security cheque. Upload details to <a href="/account/profile">My Profile</a> so your agent can prepare the contract faster.</p>', 'What documents do I need to rent an apartment in Dubai?', 5, true from public.faq_categories where slug = 'renting-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'is-agency-commission-charged-on-rentals-in-dubai', 'Is agency commission charged on rentals in Dubai?', '<p>Yes — typically 5% of annual rent plus VAT, paid once at contract signing. Commission is itemised in your payment breakdown inside <a href="/account/transactions">property applications</a>. Compare <a href="/collection/new">new listings</a> listings for transparent fee disclosure.</p>', 'Is agency commission charged on rentals in Dubai?', 6, true from public.faq_categories where slug = 'renting-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'can-i-negotiate-rent-on-a-dubai-property-listing', 'Can I negotiate rent on a Dubai property listing?', '<p>Negotiation depends on the owner and market conditions. Submit an inquiry through the listing; your agent will advise on realistic offers. Explore <a href="/collection/all">all listings</a> to compare similar units in the same area.</p>', 'Can I negotiate rent on a Dubai property listing?', 7, true from public.faq_categories where slug = 'renting-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-is-rera-and-how-does-it-protect-tenants', 'What is RERA and how does it protect tenants?', '<p>The Real Estate Regulatory Agency (RERA) regulates brokers, contracts, and escrow. GW Vacation Homes operates under RERA guidelines. Learn more on our <a href="/pages/about">About GW Vacation Homes</a> page and <a href="/pages/terms">Terms of Service</a>.</p>', 'What is RERA and how does it protect tenants?', 8, true from public.faq_categories where slug = 'renting-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'can-i-sublet-my-rental-property-in-dubai', 'Can I sublet my rental property in Dubai?', '<p>Subletting requires explicit written consent from the landlord. Unauthorized subletting can void your tenancy. Check your contract terms in <a href="/account/transactions">property applications</a> or ask via <a href="/pages/contact">contact our team</a>.</p>', 'Can I sublet my rental property in Dubai?', 9, true from public.faq_categories where slug = 'renting-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-happens-if-a-rent-cheque-bounces-in-dubai', 'What happens if a rent cheque bounces in Dubai?', '<p>Bounced cheques are a serious offence in the UAE and can lead to legal action. Ensure sufficient funds before issuing post-dated cheques. Your <a href="/pages/renting-guide">Renting Guide</a> explains cheque best practices.</p>', 'What happens if a rent cheque bounces in Dubai?', 10, true from public.faq_categories where slug = 'renting-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'are-utilities-included-in-dubai-rent', 'Are utilities included in Dubai rent?', '<p>Most long-term leases exclude DEWA (electricity/water) and district cooling (chiller). Short-term <a href="/collection/rentals">holiday and long-term rentals</a> may include utilities — check each listing. See Ejari and DEWA FAQs in this help centre.</p>', 'Are utilities included in Dubai rent?', 11, true from public.faq_categories where slug = 'renting-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'can-i-break-a-tenancy-contract-early-in-dubai', 'Can I break a tenancy contract early in Dubai?', '<p>Early termination clauses vary. Some contracts require 1–3 months'' notice and penalty fees. Review terms before signing; your agent explains options in <a href="/account/transactions">property applications</a>.</p>', 'Can I break a tenancy contract early in Dubai?', 12, true from public.faq_categories where slug = 'renting-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'do-i-need-home-insurance-as-a-tenant-in-dubai', 'Do I need home insurance as a tenant in Dubai?', '<p>Contents insurance is recommended but not always mandatory. Building insurance is typically the landlord''s responsibility. <a href="/pages/contact">contact our team</a> for partner referrals if needed.</p>', 'Do I need home insurance as a tenant in Dubai?', 13, true from public.faq_categories where slug = 'renting-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-is-a-fit-out-or-furnishing-clause-in-a-lease', 'What is a fit-out or furnishing clause in a lease?', '<p>It defines whether the unit is unfurnished, semi-furnished, or fully furnished. Listings show furnishing type on each property page. Browse <a href="/collection/rentals">holiday and long-term rentals</a> and filter by preference.</p>', 'What is a fit-out or furnishing clause in a lease?', 14, true from public.faq_categories where slug = 'renting-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'how-do-i-renew-my-tenancy-in-dubai', 'How do I renew my tenancy in Dubai?', '<p>Renewals usually start 90 days before expiry. Your agent contacts you via <a href="/account">My Account</a> notifications. Updated terms and rent adjustments are shared before re-signing.</p>', 'How do I renew my tenancy in Dubai?', 15, true from public.faq_categories where slug = 'renting-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'can-two-people-share-a-tenancy-contract-in-dubai', 'Can two people share a tenancy contract in Dubai?', '<p>Yes — joint tenancy is common. All tenants should be named on the Ejari contract. Add co-tenant details in <a href="/account/profile">My Profile</a> when applying.</p>', 'Can two people share a tenancy contract in Dubai?', 16, true from public.faq_categories where slug = 'renting-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'are-pets-allowed-in-dubai-rental-apartments', 'Are pets allowed in Dubai rental apartments?', '<p>Pet policies are owner-specific. Many buildings also have Emaar/DAMAC pet rules. Check listing amenities or <a href="/pages/contact">contact our team</a> before booking a <a href="/account/viewings">viewing requests</a>.</p>', 'Are pets allowed in Dubai rental apartments?', 17, true from public.faq_categories where slug = 'renting-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-is-a-rera-tenancy-contract-form-a-vs-form-b', 'What is a RERA tenancy contract Form A vs Form B?', '<p>Form A is the standard RERA unified tenancy contract used for most residential leases. Your agent generates the correct form through <a href="/account/transactions">property applications</a>. See <a href="/pages/renting-guide">Renting Guide</a> for the full process.</p>', 'What is a RERA tenancy contract Form A vs Form B?', 18, true from public.faq_categories where slug = 'renting-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'how-quickly-can-i-move-in-after-approving-a-rental', 'How quickly can I move in after approving a rental?', '<p>Typically 5–10 business days after contract signing and cheque clearance. Timeline appears in <a href="/pages/shipping">Handover Information</a>. Track status in <a href="/account/transactions">property applications</a>.</p>', 'How quickly can I move in after approving a rental?', 19, true from public.faq_categories where slug = 'renting-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'do-i-pay-vat-on-residential-rent-in-dubai', 'Do I pay VAT on residential rent in Dubai?', '<p>Residential rent is generally VAT-exempt. Agency fees and some admin charges may include 5% VAT — shown in your payment breakdown in <a href="/account/transactions">property applications</a>.</p>', 'Do I pay VAT on residential rent in Dubai?', 20, true from public.faq_categories where slug = 'renting-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'can-i-rent-a-property-without-a-uae-bank-account', 'Can I rent a property without a UAE bank account?', '<p>Some owners accept international transfers for short stays; long-term leases usually require UAE cheques or local bank transfer. <a href="/pages/contact">contact our team</a> to discuss options for your situation.</p>', 'Can I rent a property without a UAE bank account?', 21, true from public.faq_categories where slug = 'renting-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-is-district-cooling-and-who-pays-for-it', 'What is district cooling and who pays for it?', '<p>District cooling (Empower/Faruq) is separate from DEWA and billed monthly based on usage. Confirm whether chiller is landlord-paid or tenant-paid in your contract via <a href="/account/transactions">property applications</a>.</p>', 'What is district cooling and who pays for it?', 22, true from public.faq_categories where slug = 'renting-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'how-do-i-schedule-a-rental-viewing-in-dubai', 'How do I schedule a rental viewing in Dubai?', '<p>Open any listing and book a viewing online. Track confirmations in <a href="/account/viewings">viewing requests</a>. Read <a href="/pages/how-it-works">How It Works</a> for the full journey from inquiry to keys.</p>', 'How do I schedule a rental viewing in Dubai?', 23, true from public.faq_categories where slug = 'renting-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'where-can-i-browse-verified-rental-listings-in-dubai', 'Where can I browse verified rental listings in Dubai?', '<p>Explore <a href="/collection/rentals">holiday and long-term rentals</a>, <a href="/collection/new">new listings</a> additions, or use <a href="/search">property search</a> by area and budget. Save favourites in <a href="/account">My Account</a>.</p>', 'Where can I browse verified rental listings in Dubai?', 24, true from public.faq_categories where slug = 'renting-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'can-foreigners-buy-property-in-dubai', 'Can foreigners buy property in Dubai?', '<p>Yes — nationals of most countries can buy freehold property in designated areas. Eligibility is confirmed per listing. Start with <a href="/pages/buying-guide">Buying Guide</a> and browse <a href="/collection/sales">properties for sale</a>.</p>', 'Can foreigners buy property in Dubai?', 25, true from public.faq_categories where slug = 'buying-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-is-a-freehold-area-in-dubai', 'What is a freehold area in Dubai?', '<p>Freehold zones allow full foreign ownership (e.g. Dubai Marina, Downtown, JVC, Palm Jumeirah). Leasehold areas grant long-term rights only. Each <a href="/collection/sales">properties for sale</a> listing notes ownership type.</p>', 'What is a freehold area in Dubai?', 26, true from public.faq_categories where slug = 'buying-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'how-much-is-the-dld-transfer-fee-when-buying-in-dubai', 'How much is the DLD transfer fee when buying in Dubai?', '<p>Dubai Land Department (DLD) charges 4% of the sale price plus admin fees. Amounts appear in your transaction breakdown in <a href="/account/transactions">property applications</a> before payment.</p>', 'How much is the DLD transfer fee when buying in Dubai?', 27, true from public.faq_categories where slug = 'buying-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-is-an-oqood-vs-a-title-deed', 'What is an Oqood vs a title deed?', '<p>Oqood registers off-plan sales; title deed is issued after handover/completion. Your agent explains which stage applies in <a href="/account/transactions">property applications</a>. See <a href="/pages/buying-guide">Buying Guide</a> for off-plan vs ready property.</p>', 'What is an Oqood vs a title deed?', 28, true from public.faq_categories where slug = 'buying-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'do-i-need-a-mortgage-to-buy-property-in-dubai', 'Do I need a mortgage to buy property in Dubai?', '<p>Cash and mortgage purchases are both common. UAE residents may finance up to 80% LTV for first homes (subject to bank approval). <a href="/pages/contact">contact our team</a> for mortgage partner introductions.</p>', 'Do I need a mortgage to buy property in Dubai?', 29, true from public.faq_categories where slug = 'buying-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-is-a-booking-deposit-when-buying-in-dubai', 'What is a booking deposit when buying in Dubai?', '<p>A booking deposit (often 5–10%) secures the unit while SPA is prepared. It''s held per RERA escrow rules for off-plan. Details in <a href="/pages/buying-guide">Buying Guide</a> and <a href="/account/transactions">property applications</a>.</p>', 'What is a booking deposit when buying in Dubai?', 30, true from public.faq_categories where slug = 'buying-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'how-long-does-property-transfer-take-at-dld', 'How long does property transfer take at DLD?', '<p>Ready property transfers often complete in 1–3 weeks after NOC and funds clear. Off-plan follows developer handover schedules. Track milestones in <a href="/account/transactions">property applications</a>.</p>', 'How long does property transfer take at DLD?', 31, true from public.faq_categories where slug = 'buying-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-is-snagging-on-a-new-dubai-property', 'What is snagging on a new Dubai property?', '<p>Snagging is a pre-handover inspection listing defects for the developer to fix. We recommend snagging for new builds — <a href="/pages/shipping">Handover Information</a> explains the process.</p>', 'What is snagging on a new Dubai property?', 32, true from public.faq_categories where slug = 'buying-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'can-i-buy-off-plan-property-as-a-non-resident', 'Can I buy off-plan property as a non-resident?', '<p>Many developers sell to non-residents with passport copies and proof of funds. Payment plans vary. Browse <a href="/collection/sales">properties for sale</a> and read <a href="/pages/buying-guide">Buying Guide</a> for off-plan due diligence.</p>', 'Can I buy off-plan property as a non-resident?', 33, true from public.faq_categories where slug = 'buying-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-is-rera-escrow-for-off-plan-purchases', 'What is RERA escrow for off-plan purchases?', '<p>Buyer payments must go into RERA-approved escrow accounts for registered projects — protecting funds until construction milestones. Verified in <a href="/account/transactions">property applications</a>.</p>', 'What is RERA escrow for off-plan purchases?', 34, true from public.faq_categories where slug = 'buying-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'are-service-charges-included-when-buying-an-apartment', 'Are service charges included when buying an apartment?', '<p>Service charges are annual fees for building maintenance, separate from purchase price. Ask your agent for the latest SC rate on any <a href="/collection/sales">properties for sale</a> listing.</p>', 'Are service charges included when buying an apartment?', 35, true from public.faq_categories where slug = 'buying-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-is-a-no-objection-certificate-noc-for-resale', 'What is a No Objection Certificate (NOC) for resale?', '<p>Developers issue NOCs confirming no outstanding dues before DLD transfer. Your agent obtains NOC as part of <a href="/account/transactions">property applications</a> workflow.</p>', 'What is a No Objection Certificate (NOC) for resale?', 36, true from public.faq_categories where slug = 'buying-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'can-i-buy-property-in-dubai-through-a-company', 'Can I buy property in Dubai through a company?', '<p>Yes — corporate ownership is allowed with proper licensing and documentation. <a href="/pages/contact">contact our team</a> for corporate purchase requirements.</p>', 'Can I buy property in Dubai through a company?', 37, true from public.faq_categories where slug = 'buying-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-taxes-apply-when-buying-property-in-dubai', 'What taxes apply when buying property in Dubai?', '<p>Dubai has no annual property tax; one-time DLD 4% transfer fee applies. No capital gains tax for individuals currently. Confirm latest rules via <a href="/pages/contact">contact our team</a>.</p>', 'What taxes apply when buying property in Dubai?', 38, true from public.faq_categories where slug = 'buying-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'how-do-i-make-an-offer-on-a-dubai-property', 'How do I make an offer on a Dubai property?', '<p>Submit an inquiry on the listing with your offer terms. Your agent negotiates with the owner and updates <a href="/account/transactions">property applications</a>. Compare comps via <a href="/search">property search</a>.</p>', 'How do I make an offer on a Dubai property?', 39, true from public.faq_categories where slug = 'buying-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-is-the-difference-between-ready-and-off-plan', 'What is the difference between ready and off-plan?', '<p>Ready units are completed and transferable immediately. Off-plan is under construction with staged payments. Both appear in <a href="/collection/sales">properties for sale</a> — filter by availability.</p>', 'What is the difference between ready and off-plan?', 40, true from public.faq_categories where slug = 'buying-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'do-i-need-a-lawyer-when-buying-in-dubai', 'Do I need a lawyer when buying in Dubai?', '<p>Many buyers use the SPA prepared by the developer or agency; complex deals may need independent legal review. Contract review happens in <a href="/account/transactions">property applications</a> before you sign.</p>', 'Do I need a lawyer when buying in Dubai?', 41, true from public.faq_categories where slug = 'buying-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'can-i-buy-property-in-dubai-on-a-visit-visa', 'Can I buy property in Dubai on a visit visa?', '<p>Yes for cash purchases with valid ID; mortgage approval typically requires residency. <a href="/pages/contact">contact our team</a> to plan your purchase timeline.</p>', 'Can I buy property in Dubai on a visit visa?', 42, true from public.faq_categories where slug = 'buying-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-is-golden-visa-property-investment-threshold', 'What is Golden Visa property investment threshold?', '<p>UAE Golden Visa property routes have minimum investment thresholds (historically around AED 2M+ for certain categories — verify current GDRFA rules). <a href="/pages/contact">contact our team</a> for latest eligibility.</p>', 'What is Golden Visa property investment threshold?', 43, true from public.faq_categories where slug = 'buying-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'how-is-agency-commission-calculated-on-sales', 'How is agency commission calculated on sales?', '<p>Typically 2% of sale price plus VAT, paid by buyer or seller per agreement. Disclosed in <a href="/account/transactions">property applications</a> payment breakdown before you commit.</p>', 'How is agency commission calculated on sales?', 44, true from public.faq_categories where slug = 'buying-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-happens-at-property-handover-for-buyers', 'What happens at property handover for buyers?', '<p>Final payment, DLD transfer, and key collection. See <a href="/pages/shipping">Handover Information</a> and <a href="/pages/buying-guide">Buying Guide</a>. Status updates appear in <a href="/account">My Account</a>.</p>', 'What happens at property handover for buyers?', 45, true from public.faq_categories where slug = 'buying-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'can-i-buy-auction-property-in-dubai', 'Can I buy auction property in Dubai?', '<p>Court and bank auctions follow different rules and due diligence. Our <a href="/collection/sales">properties for sale</a> focus on standard listings — <a href="/pages/contact">contact our team</a> for auction referrals.</p>', 'Can I buy auction property in Dubai?', 46, true from public.faq_categories where slug = 'buying-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'is-property-inspection-available-before-buying', 'Is property inspection available before buying?', '<p>Yes — schedule a viewing via any listing. <a href="/account/viewings">viewing requests</a> tracks appointments. For off-plan, review developer track record in <a href="/pages/buying-guide">Buying Guide</a>.</p>', 'Is property inspection available before buying?', 47, true from public.faq_categories where slug = 'buying-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'how-do-i-verify-a-property-title-is-clean', 'How do I verify a property title is clean?', '<p>Your agent runs DLD title deed checks for liens and encumbrances before contract. Part of our <a href="/pages/how-it-works">How It Works</a> workflow.</p>', 'How do I verify a property title is clean?', 48, true from public.faq_categories where slug = 'buying-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'where-do-i-start-browsing-dubai-properties-for-sale', 'Where do I start browsing Dubai properties for sale?', '<p>Visit <a href="/collection/sales">properties for sale</a>, <a href="/collection/new">new listings</a> listings, or <a href="/search">property search</a>. Create <a href="/account">My Account</a> to save favourites and apply online.</p>', 'Where do I start browsing Dubai properties for sale?', 49, true from public.faq_categories where slug = 'buying-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'how-do-i-book-a-property-viewing-online', 'How do I book a property viewing online?', '<p>Open a listing and click Book a Viewing or submit an inquiry with preferred dates. Confirmations appear in <a href="/account/viewings">viewing requests</a> and <a href="/account">My Account</a> notifications.</p>', 'How do I book a property viewing online?', 50, true from public.faq_categories where slug = 'viewings-applications' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'can-i-reschedule-a-viewing-in-dubai', 'Can I reschedule a viewing in Dubai?', '<p>Yes — <a href="/pages/contact">contact our team</a> your agent or reply to the notification. Updated times sync to <a href="/account/viewings">viewing requests</a>.</p>', 'Can I reschedule a viewing in Dubai?', 51, true from public.faq_categories where slug = 'viewings-applications' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-should-i-bring-to-a-property-viewing', 'What should I bring to a property viewing?', '<p>Emirates ID or passport, questions list, and tape measure if furnishing planning. Complete <a href="/account/profile">My Profile</a> beforehand for faster applications.</p>', 'What should I bring to a property viewing?', 52, true from public.faq_categories where slug = 'viewings-applications' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'how-long-does-a-typical-viewing-take', 'How long does a typical viewing take?', '<p>Apartments: 20–30 minutes. Villas: 45–60 minutes. Your agent allows time for building amenities inspection.</p>', 'How long does a typical viewing take?', 53, true from public.faq_categories where slug = 'viewings-applications' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'can-i-view-multiple-properties-in-one-day', 'Can I view multiple properties in one day?', '<p>Yes — <a href="/pages/contact">contact our team</a> to arrange a viewing route. Save targets from <a href="/search">property search</a> or <a href="/collection/all">all listings</a> first.</p>', 'Can I view multiple properties in one day?', 54, true from public.faq_categories where slug = 'viewings-applications' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-happens-after-my-viewing-is-completed', 'What happens after my viewing is completed?', '<p>Declare Proceed, Not Proceed, or Need More Info in <a href="/account/transactions">property applications</a>. Your agent reviews and updates status. See <a href="/pages/how-it-works">How It Works</a>.</p>', 'What happens after my viewing is completed?', 55, true from public.faq_categories where slug = 'viewings-applications' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'how-do-i-track-my-property-application-status', 'How do I track my property application status?', '<p>Sign in to <a href="/account/transactions">property applications</a> for a step-by-step timeline: viewing → contract → payment → handover.</p>', 'How do I track my property application status?', 56, true from public.faq_categories where slug = 'viewings-applications' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'can-i-apply-for-a-property-without-a-viewing', 'Can I apply for a property without a viewing?', '<p>Some off-plan or remote buyers proceed with video tours; most owners prefer in-person viewings for ready units. <a href="/pages/contact">contact our team</a> for virtual options.</p>', 'Can I apply for a property without a viewing?', 57, true from public.faq_categories where slug = 'viewings-applications' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'how-many-properties-can-i-apply-for-at-once', 'How many properties can I apply for at once?', '<p>Multiple inquiries are fine, but serious applications should focus on 1–2 priorities. Each has a separate <a href="/account/transactions">property applications</a> record.</p>', 'How many properties can I apply for at once?', 58, true from public.faq_categories where slug = 'viewings-applications' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-is-a-property-transaction-number', 'What is a property transaction number?', '<p>A unique reference (e.g. PT-000123) for your application. Shown in <a href="/account/transactions">property applications</a> and all email notifications.</p>', 'What is a property transaction number?', 59, true from public.faq_categories where slug = 'viewings-applications' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'who-is-my-assigned-agent', 'Who is my assigned agent?', '<p>Displayed in <a href="/account/transactions">property applications</a> and viewing confirmations. <a href="/pages/about">About GW Vacation Homes</a> introduces our agent standards.</p>', 'Who is my assigned agent?', 60, true from public.faq_categories where slug = 'viewings-applications' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'can-my-spouse-join-the-application', 'Can my spouse join the application?', '<p>Yes — add co-applicant details in <a href="/account/profile">My Profile</a> and inform your agent via <a href="/pages/contact">contact our team</a>.</p>', 'Can my spouse join the application?', 61, true from public.faq_categories where slug = 'viewings-applications' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'how-fast-do-agents-respond-to-inquiries', 'How fast do agents respond to inquiries?', '<p>We aim within one business day. Urgent requests: <a href="/pages/contact">contact our team</a> or WhatsApp from any listing page.</p>', 'How fast do agents respond to inquiries?', 62, true from public.faq_categories where slug = 'viewings-applications' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-if-the-property-is-already-under-offer', 'What if the property is already under offer?', '<p>Your agent notifies you immediately and suggests similar <a href="/collection/new">new listings</a> or <a href="/search">property search</a> alternatives.</p>', 'What if the property is already under offer?', 63, true from public.faq_categories where slug = 'viewings-applications' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'do-i-need-an-account-to-book-a-viewing', 'Do I need an account to book a viewing?', '<p>An account lets you track <a href="/account/viewings">viewing requests</a> and <a href="/account/transactions">property applications</a>. Guest inquiries are possible but limit dashboard tracking — sign up via <a href="/account">My Account</a>.</p>', 'Do I need an account to book a viewing?', 64, true from public.faq_categories where slug = 'viewings-applications' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'can-i-cancel-a-viewing-request', 'Can I cancel a viewing request?', '<p>Yes — notify your agent before the scheduled time. Status updates in <a href="/account/viewings">viewing requests</a>.</p>', 'Can I cancel a viewing request?', 65, true from public.faq_categories where slug = 'viewings-applications' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-is-client-declaration-after-viewing', 'What is client declaration after viewing?', '<p>Your formal Proceed / Not Proceed response that unlocks contract stage if approved. Submit inside <a href="/account/transactions">property applications</a>.</p>', 'What is client declaration after viewing?', 66, true from public.faq_categories where slug = 'viewings-applications' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'how-do-notifications-work-for-my-application', 'How do notifications work for my application?', '<p>Email and in-app alerts for viewing updates, contracts, and payments. Manage in <a href="/account">My Account</a> notifications settings.</p>', 'How do notifications work for my application?', 67, true from public.faq_categories where slug = 'viewings-applications' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'can-agents-show-properties-on-weekends', 'Can agents show properties on weekends?', '<p>Many viewings happen Friday–Saturday. Request preferred slots when booking or via <a href="/pages/contact">contact our team</a>.</p>', 'Can agents show properties on weekends?', 68, true from public.faq_categories where slug = 'viewings-applications' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'where-is-the-full-step-by-step-application-guide', 'Where is the full step-by-step application guide?', '<p>Read <a href="/pages/how-it-works">How It Works</a> for inquiry → viewing → contract → payment → handover. Rent-specific: <a href="/pages/renting-guide">Renting Guide</a>. Buy-specific: <a href="/pages/buying-guide">Buying Guide</a>.</p>', 'Where is the full step-by-step application guide?', 69, true from public.faq_categories where slug = 'viewings-applications' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'when-do-i-receive-my-tenancy-contract', 'When do I receive my tenancy contract?', '<p>After agent approval of your application and contract request in <a href="/account/transactions">property applications</a>. Download from your dashboard when ready.</p>', 'When do I receive my tenancy contract?', 70, true from public.faq_categories where slug = 'contracts-legal' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'how-do-i-upload-a-signed-contract', 'How do I upload a signed contract?', '<p>Sign the PDF, scan or photograph, upload in <a href="/account/transactions">property applications</a>. Agent reviews within 1–2 business days.</p>', 'How do I upload a signed contract?', 71, true from public.faq_categories where slug = 'contracts-legal' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-if-my-signed-contract-is-rejected', 'What if my signed contract is rejected?', '<p>Agent requests re-upload with notes — fix signatures, dates, or initials and resubmit via <a href="/account/transactions">property applications</a>.</p>', 'What if my signed contract is rejected?', 72, true from public.faq_categories where slug = 'contracts-legal' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'is-the-tenancy-contract-legally-binding-in-dubai', 'Is the tenancy contract legally binding in Dubai?', '<p>Yes — once signed and Ejari-registered per RERA. Review <a href="/pages/terms">Terms of Service</a> and ask questions before signing.</p>', 'Is the tenancy contract legally binding in Dubai?', 73, true from public.faq_categories where slug = 'contracts-legal' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-is-a-sale-and-purchase-agreement-spa', 'What is a Sale and Purchase Agreement (SPA)?', '<p>The binding contract for property sales outlining price, payment plan, and completion date. Generated through <a href="/account/transactions">property applications</a> for buyers.</p>', 'What is a Sale and Purchase Agreement (SPA)?', 74, true from public.faq_categories where slug = 'contracts-legal' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'can-i-review-a-contract-before-committing', 'Can I review a contract before committing?', '<p>Yes — contracts are shared for review before payment. Never pay before reviewing your breakdown in <a href="/account/transactions">property applications</a>.</p>', 'Can I review a contract before committing?', 75, true from public.faq_categories where slug = 'contracts-legal' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-personal-data-goes-on-a-contract', 'What personal data goes on a contract?', '<p>Name, ID, contact, and property details from <a href="/account/profile">My Profile</a>. Keep <a href="/account/profile">My Profile</a> updated for accuracy.</p>', 'What personal data goes on a contract?', 76, true from public.faq_categories where slug = 'contracts-legal' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'are-digital-signatures-accepted', 'Are digital signatures accepted?', '<p>Scanned wet signatures are standard; some developers accept e-sign. Your agent confirms format in <a href="/account/transactions">property applications</a>.</p>', 'Are digital signatures accepted?', 77, true from public.faq_categories where slug = 'contracts-legal' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-is-an-addendum-to-a-tenancy-contract', 'What is an addendum to a tenancy contract?', '<p>A supplemental document modifying terms (e.g. pet clause, maintenance). Attached to main contract in <a href="/account/transactions">property applications</a>.</p>', 'What is an addendum to a tenancy contract?', 78, true from public.faq_categories where slug = 'contracts-legal' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'who-holds-the-original-tenancy-contract', 'Who holds the original tenancy contract?', '<p>Both parties receive copies; Ejari registration holds the official record. Digital copies in <a href="/account/transactions">property applications</a>.</p>', 'Who holds the original tenancy contract?', 79, true from public.faq_categories where slug = 'contracts-legal' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-is-rera-form-f-for-sales', 'What is RERA Form F for sales?', '<p>Memorandum of Understanding between buyer and seller before SPA. Used in resale <a href="/collection/sales">properties for sale</a> transactions.</p>', 'What is RERA Form F for sales?', 80, true from public.faq_categories where slug = 'contracts-legal' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'can-i-assign-my-off-plan-contract-to-another-buyer', 'Can I assign my off-plan contract to another buyer?', '<p>Developer assignment policies vary; fees may apply. <a href="/pages/contact">contact our team</a> before any assignment.</p>', 'Can I assign my off-plan contract to another buyer?', 81, true from public.faq_categories where slug = 'contracts-legal' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-happens-if-the-seller-withdraws-after-mou', 'What happens if the seller withdraws after MOU?', '<p>MOU terms define forfeiture and remedies. Legal review recommended for high-value deals — <a href="/pages/contact">contact our team</a>.</p>', 'What happens if the seller withdraws after MOU?', 82, true from public.faq_categories where slug = 'contracts-legal' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'is-my-contract-data-kept-private', 'Is my contract data kept private?', '<p>Yes — per <a href="/pages/privacy">Privacy Policy</a>. Only assigned agents and admins access <a href="/account/transactions">property applications</a> documents.</p>', 'Is my contract data kept private?', 83, true from public.faq_categories where slug = 'contracts-legal' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-language-are-contracts-written-in', 'What language are contracts written in?', '<p>English is standard; Arabic versions may be provided for official registration. Bilingual Ejari is common.</p>', 'What language are contracts written in?', 84, true from public.faq_categories where slug = 'contracts-legal' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'do-i-need-attestation-for-overseas-buyers', 'Do I need attestation for overseas buyers?', '<p>Some transactions require notarized documents from abroad. <a href="/pages/contact">contact our team</a> for country-specific requirements.</p>', 'Do I need attestation for overseas buyers?', 85, true from public.faq_categories where slug = 'contracts-legal' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-is-a-security-cheque-vs-rental-cheque', 'What is a security cheque vs rental cheque?', '<p>Security cheque covers damages (refundable); rental cheques pay rent per schedule. Both explained in <a href="/pages/renting-guide">Renting Guide</a>.</p>', 'What is a security cheque vs rental cheque?', 86, true from public.faq_categories where slug = 'contracts-legal' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'can-contract-terms-be-negotiated', 'Can contract terms be negotiated?', '<p>Some clauses (rent, cheques, break terms) are negotiable with owner approval. Your agent advocates during <a href="/account/transactions">property applications</a>.</p>', 'Can contract terms be negotiated?', 87, true from public.faq_categories where slug = 'contracts-legal' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'how-long-is-contract-review-turnaround', 'How long is contract review turnaround?', '<p>Agent review of uploaded contracts: typically 1–2 business days. You are notified in <a href="/account">My Account</a>.</p>', 'How long is contract review turnaround?', 88, true from public.faq_categories where slug = 'contracts-legal' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'where-are-contract-and-legal-faqs-for-handover', 'Where are contract and legal FAQs for handover?', '<p>See <a href="/pages/shipping">Handover Information</a> for post-contract steps and this section for signing. Full journey: <a href="/pages/how-it-works">How It Works</a>.</p>', 'Where are contract and legal FAQs for handover?', 89, true from public.faq_categories where slug = 'contracts-legal' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'when-can-i-pay-for-my-property-application', 'When can I pay for my property application?', '<p>After signed contract approval and invoice generation in <a href="/account/transactions">property applications</a>. See payment section when status is Payment Pending.</p>', 'When can I pay for my property application?', 90, true from public.faq_categories where slug = 'payments-fees' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-appears-in-my-payment-breakdown', 'What appears in my payment breakdown?', '<p>Rent or sale price, deposit, agency commission, admin fees, Ejari, VAT where applicable. Itemised before invoice in <a href="/account/transactions">property applications</a>.</p>', 'What appears in my payment breakdown?', 91, true from public.faq_categories where slug = 'payments-fees' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'can-i-pay-online-with-a-card', 'Can I pay online with a card?', '<p>Yes — when Stripe checkout is enabled, pay securely from <a href="/account/transactions">property applications</a>. Otherwise bank transfer with manual confirmation.</p>', 'Can I pay online with a card?', 92, true from public.faq_categories where slug = 'payments-fees' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'is-my-online-payment-secure', 'Is my online payment secure?', '<p>Card payments process via Stripe; we never store full card numbers. See <a href="/pages/privacy">Privacy Policy</a> for data handling.</p>', 'Is my online payment secure?', 93, true from public.faq_categories where slug = 'payments-fees' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-currency-are-payments-in', 'What currency are payments in?', '<p>AED (UAE Dirham) for Dubai properties. Display follows site currency settings on listings.</p>', 'What currency are payments in?', 94, true from public.faq_categories where slug = 'payments-fees' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'when-is-the-invoice-generated', 'When is the invoice generated?', '<p>After agent builds payment breakdown — you or your agent creates invoice in <a href="/account/transactions">property applications</a>.</p>', 'When is the invoice generated?', 95, true from public.faq_categories where slug = 'payments-fees' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'can-i-pay-in-instalments-for-a-sale', 'Can I pay in instalments for a sale?', '<p>Off-plan follows developer payment plans; ready sales usually require staged payments per SPA. Details in <a href="/pages/buying-guide">Buying Guide</a> and <a href="/account/transactions">property applications</a>.</p>', 'Can I pay in instalments for a sale?', 96, true from public.faq_categories where slug = 'payments-fees' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-if-my-payment-fails-online', 'What if my payment fails online?', '<p>Retry from <a href="/account/transactions">property applications</a> or <a href="/pages/contact">contact our team</a> for bank transfer instructions. Invoice stays pending until paid.</p>', 'What if my payment fails online?', 97, true from public.faq_categories where slug = 'payments-fees' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'are-refunds-available-after-payment', 'Are refunds available after payment?', '<p>Refund rules depend on contract stage and owner policy. Deposits may be non-refundable after MOU/SPA — review <a href="/pages/terms">Terms of Service</a>.</p>', 'Are refunds available after payment?', 98, true from public.faq_categories where slug = 'payments-fees' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'who-receives-my-payment', 'Who receives my payment?', '<p>Agency fees to GW Vacation Homes; rent/sale funds per contract (owner/developer/escrow). Breakdown clarifies each line in <a href="/account/transactions">property applications</a>.</p>', 'Who receives my payment?', 99, true from public.faq_categories where slug = 'payments-fees' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'do-i-get-a-receipt-after-payment', 'Do I get a receipt after payment?', '<p>Yes — invoice marked paid in <a href="/account/transactions">property applications</a> with confirmation notification. Email receipt when Stripe is used.</p>', 'Do I get a receipt after payment?', 100, true from public.faq_categories where slug = 'payments-fees' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-is-the-agency-commission-on-rent', 'What is the agency commission on rent?', '<p>Typically 5% of annual rent + VAT. Shown in breakdown before you pay — browse <a href="/collection/rentals">holiday and long-term rentals</a> with confidence.</p>', 'What is the agency commission on rent?', 101, true from public.faq_categories where slug = 'payments-fees' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-is-the-agency-commission-on-sales', 'What is the agency commission on sales?', '<p>Typically 2% of sale price + VAT unless otherwise agreed. Disclosed in <a href="/account/transactions">property applications</a>.</p>', 'What is the agency commission on sales?', 102, true from public.faq_categories where slug = 'payments-fees' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'are-admin-fees-mandatory', 'Are admin fees mandatory?', '<p>Admin/Ejari fees cover registration and processing — itemised in breakdown. See <a href="/pages/renting-guide">Renting Guide</a> for typical ranges.</p>', 'Are admin fees mandatory?', 103, true from public.faq_categories where slug = 'payments-fees' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'can-i-pay-from-outside-the-uae', 'Can I pay from outside the UAE?', '<p>International wire accepted for many transactions. <a href="/pages/contact">contact our team</a> for SWIFT details and currency conversion notes.</p>', 'Can I pay from outside the UAE?', 104, true from public.faq_categories where slug = 'payments-fees' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'when-is-the-security-deposit-due', 'When is the security deposit due?', '<p>Usually at contract signing with first rent cheque. Timeline in <a href="/account/transactions">property applications</a> payment schedule.</p>', 'When is the security deposit due?', 105, true from public.faq_categories where slug = 'payments-fees' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'does-vat-apply-to-agency-fees', 'Does VAT apply to agency fees?', '<p>Yes — 5% UAE VAT on taxable agency services. Included in breakdown total in <a href="/account/transactions">property applications</a>.</p>', 'Does VAT apply to agency fees?', 106, true from public.faq_categories where slug = 'payments-fees' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'how-do-i-confirm-a-bank-transfer-payment', 'How do I confirm a bank transfer payment?', '<p>Upload proof or click Confirm Payment in <a href="/account/transactions">property applications</a> if quote mode is enabled. Agent verifies and updates status.</p>', 'How do I confirm a bank transfer payment?', 107, true from public.faq_categories where slug = 'payments-fees' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-payment-methods-are-accepted', 'What payment methods are accepted?', '<p>Visa, Mastercard, Amex (via Stripe where enabled), bank transfer, and post-dated cheques for rent per contract.</p>', 'What payment methods are accepted?', 108, true from public.faq_categories where slug = 'payments-fees' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'where-do-i-see-payment-history', 'Where do I see payment history?', '<p>Inside each transaction in <a href="/account/transactions">property applications</a> — invoices and payment status per property.</p>', 'Where do I see payment history?', 109, true from public.faq_categories where slug = 'payments-fees' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'how-do-i-register-ejari-for-my-tenancy', 'How do I register Ejari for my tenancy?', '<p>We coordinate Ejari after contract signing and initial payment. Required documents listed in <a href="/pages/shipping">Handover Information</a> and <a href="/pages/renting-guide">Renting Guide</a>.</p>', 'How do I register Ejari for my tenancy?', 110, true from public.faq_categories where slug = 'ejari-dewa-utilities' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'how-much-does-ejari-registration-cost', 'How much does Ejari registration cost?', '<p>Ejari fees are approximately AED 220 including VAT — included in your <a href="/account/transactions">property applications</a> breakdown when applicable.</p>', 'How much does Ejari registration cost?', 111, true from public.faq_categories where slug = 'ejari-dewa-utilities' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'how-do-i-connect-dewa-electricity-and-water', 'How do I connect DEWA electricity and water?', '<p>Apply online at DEWA with Ejari, ID, and deposit (typically AED 2,130 for apartments). We guide you at handover — <a href="/pages/shipping">Handover Information</a>.</p>', 'How do I connect DEWA electricity and water?', 112, true from public.faq_categories where slug = 'ejari-dewa-utilities' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-is-a-dewa-security-deposit', 'What is a DEWA security deposit?', '<p>Refundable deposit held by DEWA — AED 2,000 apartments / AED 4,000 villas (approx.). Refunded minus final bill on move-out.</p>', 'What is a DEWA security deposit?', 113, true from public.faq_categories where slug = 'ejari-dewa-utilities' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'how-long-does-dewa-activation-take', 'How long does DEWA activation take?', '<p>Usually 1–24 hours after application with valid Ejari. Plan activation for handover day in <a href="/account/transactions">property applications</a>.</p>', 'How long does DEWA activation take?', 114, true from public.faq_categories where slug = 'ejari-dewa-utilities' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-is-district-cooling-vs-dewa', 'What is district cooling vs DEWA?', '<p>DEWA covers electricity and water; district cooling (Empower) is separate chilled water AC billing. Confirm payer in lease via <a href="/account/transactions">property applications</a>.</p>', 'What is district cooling vs DEWA?', 115, true from public.faq_categories where slug = 'ejari-dewa-utilities' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'can-the-previous-tenant-dewa-account-be-transferred', 'Can the previous tenant DEWA account be transferred?', '<p>Final bill must close old account before new registration. Coordinate move-in/out dates with agent via <a href="/pages/contact">contact our team</a>.</p>', 'Can the previous tenant DEWA account be transferred?', 116, true from public.faq_categories where slug = 'ejari-dewa-utilities' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'how-do-i-set-up-home-internet-in-dubai', 'How do I set up home internet in Dubai?', '<p>Etisalat or du after Ejari — choose fiber plan. Not included in agency fees; arrange post handover.</p>', 'How do I set up home internet in Dubai?', 117, true from public.faq_categories where slug = 'ejari-dewa-utilities' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'is-chiller-included-in-rent', 'Is chiller included in rent?', '<p>Listing-specific. Some landlords include capped chiller; others bill tenant directly. Check listing or <a href="/account/transactions">property applications</a> contract.</p>', 'Is chiller included in rent?', 118, true from public.faq_categories where slug = 'ejari-dewa-utilities' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-happens-to-ejari-when-i-move-out', 'What happens to Ejari when I move out?', '<p>Cancel Ejari after final DEWA bill and deposit return. Agent advises on notice period per <a href="/pages/renting-guide">Renting Guide</a>.</p>', 'What happens to Ejari when I move out?', 119, true from public.faq_categories where slug = 'ejari-dewa-utilities' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'do-short-term-rentals-need-ejari', 'Do short-term rentals need Ejari?', '<p>Holiday lets under DTCM holiday home rules may differ from long-term Ejari. <a href="/pages/contact">contact our team</a> for your rental type.</p>', 'Do short-term rentals need Ejari?', 120, true from public.faq_categories where slug = 'ejari-dewa-utilities' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'can-ejari-be-done-without-an-agent', 'Can Ejari be done without an agent?', '<p>Yes via Dubai REST app, but agencies typically handle it for accuracy. Included in our <a href="/pages/how-it-works">How It Works</a> service.</p>', 'Can Ejari be done without an agent?', 121, true from public.faq_categories where slug = 'ejari-dewa-utilities' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-documents-does-ejari-require', 'What documents does Ejari require?', '<p>Signed tenancy contract, landlord title deed copy, tenant passport/Emirates ID, DEWA premise number. Prepare via <a href="/account/profile">My Profile</a>.</p>', 'What documents does Ejari require?', 122, true from public.faq_categories where slug = 'ejari-dewa-utilities' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'how-do-i-update-ejari-for-contract-renewal', 'How do I update Ejari for contract renewal?', '<p>Renew through Ejari system with new contract dates — agent handles on renewal in <a href="/account/transactions">property applications</a>.</p>', 'How do I update Ejari for contract renewal?', 123, true from public.faq_categories where slug = 'ejari-dewa-utilities' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'where-can-i-learn-more-about-move-in-utilities', 'Where can I learn more about move-in utilities?', '<p><a href="/pages/shipping">Handover Information</a> and <a href="/pages/renting-guide">Renting Guide</a> cover DEWA, Ejari, and key collection in detail.</p>', 'Where can I learn more about move-in utilities?', 124, true from public.faq_categories where slug = 'ejari-dewa-utilities' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'when-is-handover-scheduled-after-payment', 'When is handover scheduled after payment?', '<p>Agent schedules once payment is confirmed — typically within days for rentals, per SPA for sales. Track in <a href="/account/transactions">property applications</a>.</p>', 'When is handover scheduled after payment?', 125, true from public.faq_categories where slug = 'handover-move-in' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-should-i-inspect-at-handover', 'What should I inspect at handover?', '<p>Fixtures, appliances, AC, plumbing, meters readings, and community access cards. Report issues within 48 hours per <a href="/pages/shipping">Handover Information</a>.</p>', 'What should I inspect at handover?', 126, true from public.faq_categories where slug = 'handover-move-in' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'who-attends-the-handover-meeting', 'Who attends the handover meeting?', '<p>Tenant/buyer, agent, sometimes landlord or building manager. Details in handover notification via <a href="/account">My Account</a>.</p>', 'Who attends the handover meeting?', 127, true from public.faq_categories where slug = 'handover-move-in' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-documents-do-i-bring-on-handover-day', 'What documents do I bring on handover day?', '<p>Emirates ID/passport, paid invoice proof, signed contract copy, and cheques if not yet collected. List in <a href="/pages/shipping">Handover Information</a>.</p>', 'What documents do I bring on handover day?', 128, true from public.faq_categories where slug = 'handover-move-in' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'how-do-i-get-building-access-cards-and-parking', 'How do I get building access cards and parking?', '<p>Issued at handover or from building management — agent coordinates. Notes appear in <a href="/account/transactions">property applications</a> handover section.</p>', 'How do I get building access cards and parking?', 129, true from public.faq_categories where slug = 'handover-move-in' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-is-a-handover-checklist', 'What is a handover checklist?', '<p>Itemised list of keys, remotes, meter readings, and condition notes. Available for tenants post lease activation in tenant portal.</p>', 'What is a handover checklist?', 130, true from public.faq_categories where slug = 'handover-move-in' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'can-handover-be-done-remotely', 'Can handover be done remotely?', '<p>Power of attorney or authorized representative possible with notarized documents. <a href="/pages/contact">contact our team</a> to arrange.</p>', 'Can handover be done remotely?', 131, true from public.faq_categories where slug = 'handover-move-in' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-if-defects-are-found-at-handover', 'What if defects are found at handover?', '<p>Document with photos; landlord/developer fixes per contract. Snagging applies to new builds — <a href="/pages/buying-guide">Buying Guide</a>.</p>', 'What if defects are found at handover?', 132, true from public.faq_categories where slug = 'handover-move-in' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'when-do-i-receive-keys', 'When do I receive keys?', '<p>After payment clearance, Ejari (rentals), and signed handover protocol. <a href="/pages/shipping">Handover Information</a> explains timing.</p>', 'When do I receive keys?', 133, true from public.faq_categories where slug = 'handover-move-in' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'how-is-move-in-date-communicated', 'How is move-in date communicated?', '<p>Email and <a href="/account">My Account</a> notification with date, time, location, and agent contact.</p>', 'How is move-in date communicated?', 134, true from public.faq_categories where slug = 'handover-move-in' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-about-furniture-delivery-after-handover', 'What about furniture delivery after handover?', '<p>Coordinate with building rules for elevator booking and working hours. Common in Marina/Downtown towers.</p>', 'What about furniture delivery after handover?', 135, true from public.faq_categories where slug = 'handover-move-in' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'is-professional-cleaning-required-before-move-in', 'Is professional cleaning required before move-in?', '<p>Contract may require professional clean — verify in lease. Standard in premium <a href="/collection/rentals">holiday and long-term rentals</a>.</p>', 'Is professional cleaning required before move-in?', 136, true from public.faq_categories where slug = 'handover-move-in' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'can-i-pre-book-dewa-before-handover', 'Can I pre-book DEWA before handover?', '<p>Yes once Ejari is active — align activation date with key collection per <a href="/pages/renting-guide">Renting Guide</a>.</p>', 'Can I pre-book DEWA before handover?', 137, true from public.faq_categories where slug = 'handover-move-in' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-happens-after-handover-is-marked-complete', 'What happens after handover is marked complete?', '<p>Transaction status becomes Completed in <a href="/account/transactions">property applications</a>. Rentals may activate tenant portal for ongoing rent.</p>', 'What happens after handover is marked complete?', 138, true from public.faq_categories where slug = 'handover-move-in' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'where-is-the-full-handover-guide', 'Where is the full handover guide?', '<p>Read <a href="/pages/shipping">Handover Information</a> for rental and sale completion steps, plus <a href="/pages/how-it-works">How It Works</a> for the full journey.</p>', 'Where is the full handover guide?', 139, true from public.faq_categories where slug = 'handover-move-in' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-rental-yield-can-i-expect-in-dubai', 'What rental yield can I expect in Dubai?', '<p>Yields vary by area — often 5–8% gross for apartments, lower for premium Palm/Downtown. Compare <a href="/collection/sales">properties for sale</a> and <a href="/pages/contact">contact our team</a> for analysis.</p>', 'What rental yield can I expect in Dubai?', 140, true from public.faq_categories where slug = 'investment-roi' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'is-dubai-property-a-good-investment-in-2026', 'Is Dubai property a good investment in 2026?', '<p>Market depends on area, supply, and visa policies. Review <a href="/collection/new">new listings</a> listings and <a href="/pages/buying-guide">Buying Guide</a> before investing.</p>', 'Is Dubai property a good investment in 2026?', 141, true from public.faq_categories where slug = 'investment-roi' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'can-i-earn-from-holiday-home-rentals', 'Can I earn from holiday home rentals?', '<p>Yes — short-term <a href="/collection/rentals">holiday and long-term rentals</a> in licensed holiday homes can generate seasonal income. Check DTCM licensing for your building.</p>', 'Can I earn from holiday home rentals?', 142, true from public.faq_categories where slug = 'investment-roi' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-is-the-difference-between-gross-and-net-yield', 'What is the difference between gross and net yield?', '<p>Gross = annual rent / price; net deducts service charges, maintenance, and vacancy. Agent provides estimates on <a href="/pages/contact">contact our team</a>.</p>', 'What is the difference between gross and net yield?', 143, true from public.faq_categories where slug = 'investment-roi' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'should-i-buy-off-plan-for-investment', 'Should I buy off-plan for investment?', '<p>Off-plan offers payment plans and potential capital gain but carries completion risk. Due diligence in <a href="/pages/buying-guide">Buying Guide</a>.</p>', 'Should I buy off-plan for investment?', 144, true from public.faq_categories where slug = 'investment-roi' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'which-dubai-areas-have-highest-rental-demand', 'Which Dubai areas have highest rental demand?', '<p>Marina, JVC, Business Bay, and Downtown remain strong for tenants. Browse <a href="/search">property search</a> by community.</p>', 'Which Dubai areas have highest rental demand?', 145, true from public.faq_categories where slug = 'investment-roi' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'can-non-residents-collect-rent-remotely', 'Can non-residents collect rent remotely?', '<p>Yes with property management and proper accounting. <a href="/pages/contact">contact our team</a> for management referrals.</p>', 'Can non-residents collect rent remotely?', 146, true from public.faq_categories where slug = 'investment-roi' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-are-service-charges-impact-on-roi', 'What are service charges impact on ROI?', '<p>SC reduces net yield — typically AED 12–25/sq ft annually. Request SC on any <a href="/collection/sales">properties for sale</a> listing.</p>', 'What are service charges impact on ROI?', 147, true from public.faq_categories where slug = 'investment-roi' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'is-flipping-property-allowed-in-dubai', 'Is flipping property allowed in Dubai?', '<p>Resale before handover may need developer NOC and fees. Hold period affects ROI — see <a href="/pages/buying-guide">Buying Guide</a>.</p>', 'Is flipping property allowed in Dubai?', 148, true from public.faq_categories where slug = 'investment-roi' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'where-do-i-browse-investment-ready-listings', 'Where do I browse investment-ready listings?', '<p><a href="/collection/sales">properties for sale</a>, <a href="/collection/new">new listings</a>, and <a href="/collection/all">all listings</a>. <a href="/pages/about">About GW Vacation Homes</a> describes our advisory approach for investors.</p>', 'Where do I browse investment-ready listings?', 149, true from public.faq_categories where slug = 'investment-roi' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
